/// Immutable proof that the exact validated PrismCode packet authorized the
/// native MD policy before any CUDA context or engine was constructed.
///
/// This is deliberately a policy identity, not an engine-flag bundle.  The
/// engine CLI remains the sole owner of raw defaults and launch arguments.
#[derive(Clone, Debug, Deserialize, Serialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct PrismCodeMdPolicyAdmissionV1 {
    pub schema_kind: String,
    pub schema_version: u32,
    pub status: String,
    pub validated_before_cuda: bool,
    pub packet_sha256: String,
    pub packet_hash_blake3: String,
    pub packet_bytes: u64,
    pub instruction_count: u64,
    pub policy: MdEnginePolicyV1,
}

/// Compare packet-derived authority with the resolved native launch intent.
/// The caller must invoke this pure gate before constructing a CUDA engine.
pub fn admit_prismcode_md_policy_before_cuda(
    validated: Option<&ValidatedMdEnginePolicyV1>,
    expected: &MdEnginePolicyV1,
) -> Result<PrismCodeMdPolicyAdmissionV1> {
    let validated = validated.context(
        "PrismCode MD policy admission requires an exact validated packet policy before CUDA",
    )?;
    if validated.policy != *expected {
        bail!(
            "PrismCode MD packet policy differs from resolved native launch intent: packet={:?} native={:?}",
            validated.policy,
            expected
        );
    }
    if validated.packet_sha256.len() != 64
        || !validated
            .packet_sha256
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        || validated.packet_hash_blake3.len() != 64
        || !validated
            .packet_hash_blake3
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        || validated.packet_bytes == 0
        || validated.instruction_count == 0
    {
        bail!("PrismCode MD policy admission received malformed packet identity evidence");
    }
    Ok(PrismCodeMdPolicyAdmissionV1 {
        schema_kind: "prismos_prismcode_md_policy_admission".to_string(),
        schema_version: 1,
        status: "AUTHORIZED".to_string(),
        validated_before_cuda: true,
        packet_sha256: validated.packet_sha256.clone(),
        packet_hash_blake3: validated.packet_hash_blake3.clone(),
        packet_bytes: validated.packet_bytes,
        instruction_count: validated.instruction_count,
        policy: validated.policy.clone(),
    })
}

/// Enforce the retained packet-derived authority at the last production seam
/// before native PrismCode runtime state can be enabled on an engine.
///
/// Non-governed compatibility callers may leave the admission absent only when
/// they also decline complete native-runtime authority. A complete/governed
/// launch must retain the exact canonical policy and immutable packet identity.
pub fn require_prismcode_md_policy_admission_for_launch(
    admission: Option<&PrismCodeMdPolicyAdmissionV1>,
    require_complete: bool,
) -> Result<Option<&PrismCodeMdPolicyAdmissionV1>> {
    let Some(admission) = admission else {
        if require_complete {
            bail!("governed PrismCode native runtime lacks packet-derived policy admission");
        }
        return Ok(None);
    };
    if admission.schema_kind != "prismos_prismcode_md_policy_admission"
        || admission.schema_version != 1
        || admission.status != "AUTHORIZED"
        || !admission.validated_before_cuda
        || admission.packet_sha256.len() != 64
        || !admission
            .packet_sha256
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        || admission.packet_hash_blake3.len() != 64
        || !admission
            .packet_hash_blake3
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        || admission.packet_bytes == 0
        || admission.instruction_count == 0
    {
        bail!("PrismCode native launch admission identity is malformed or unauthorized");
    }
    if require_complete
        && admission.policy != MdEnginePolicyV1::canonical_hyper_runtime()
        && admission.policy != MdEnginePolicyV1::therm_postmd()
    {
        bail!("governed PrismCode native launch admission policy is not canonical Hyper-Runtime or Therm post-MD");
    }
    Ok(Some(admission))
}

fn host_fused_observation_aligned(requested: u32, device_inner: i32, counter: i32) -> bool {
    requested > 0
        && requested <= i32::MAX as u32
        && device_inner == requested as i32
        && counter == 0
}

#[cfg(test)]
mod host_fused_observation_alignment_tests {
    use super::host_fused_observation_aligned;

    #[test]
    fn complete_groups_allow_host_entry_but_partial_resident_groups_do_not() {
        for inner in [1u32, 6, 12] {
            assert!(host_fused_observation_aligned(inner, inner as i32, 0));
            for counter in 1..inner as i32 {
                assert!(!host_fused_observation_aligned(
                    inner,
                    inner as i32,
                    counter
                ));
            }
        }
        assert!(!host_fused_observation_aligned(6, 6, 500 % 6));
        assert!(!host_fused_observation_aligned(12, 12, 1007 % 12));
        assert!(!host_fused_observation_aligned(6, 12, 0));
        assert!(!host_fused_observation_aligned(0, 0, 0));
        assert!(!host_fused_observation_aligned(u32::MAX, -1, 0));
        assert!(!host_fused_observation_aligned(6, 6, -1));
    }
}

#[cfg(test)]
mod prismcode_md_policy_admission_tests {
    use super::*;

    fn validated(policy: MdEnginePolicyV1) -> ValidatedMdEnginePolicyV1 {
        ValidatedMdEnginePolicyV1 {
            policy,
            packet_hash_blake3: "a".repeat(64),
            packet_sha256: "b".repeat(64),
            packet_bytes: 4096,
            instruction_count: 24,
        }
    }

    #[test]
    fn exact_packet_policy_is_authorized_before_cuda() {
        let expected = MdEnginePolicyV1::canonical_hyper_runtime();
        let admission =
            admit_prismcode_md_policy_before_cuda(Some(&validated(expected.clone())), &expected)
                .expect("exact policy admission");
        assert!(admission.validated_before_cuda);
        assert_eq!(admission.status, "AUTHORIZED");
        assert_eq!(admission.policy, expected);
    }

    #[test]
    fn missing_packet_policy_fails_closed_before_cuda() {
        let error = admit_prismcode_md_policy_before_cuda(
            None,
            &MdEnginePolicyV1::canonical_hyper_runtime(),
        )
        .unwrap_err();
        assert!(error
            .to_string()
            .contains("requires an exact validated packet policy"));
    }

    #[test]
    fn mismatched_packet_policy_fails_closed_before_cuda() {
        let expected = MdEnginePolicyV1::canonical_hyper_runtime();
        let mut different = expected.clone();
        different.hotpath_acceleration_required = false;
        let error = admit_prismcode_md_policy_before_cuda(Some(&validated(different)), &expected)
            .unwrap_err();
        assert!(error
            .to_string()
            .contains("differs from resolved native launch intent"));
    }

    #[test]
    fn governed_launch_guard_rejects_missing_and_mismatched_admission() {
        let missing = require_prismcode_md_policy_admission_for_launch(None, true).unwrap_err();
        assert!(missing
            .to_string()
            .contains("lacks packet-derived policy admission"));

        let expected = MdEnginePolicyV1::canonical_hyper_runtime();
        let mut admission =
            admit_prismcode_md_policy_before_cuda(Some(&validated(expected.clone())), &expected)
                .expect("fixture admission");
        admission.policy.hotpath_acceleration_required = false;
        let mismatch =
            require_prismcode_md_policy_admission_for_launch(Some(&admission), true).unwrap_err();
        assert!(mismatch
            .to_string()
            .contains("is not canonical Hyper-Runtime"));
    }

    #[test]
    fn governed_launch_guard_retains_exact_packet_identity() {
        let expected = MdEnginePolicyV1::canonical_hyper_runtime();
        let admission =
            admit_prismcode_md_policy_before_cuda(Some(&validated(expected.clone())), &expected)
                .expect("fixture admission");
        let retained = require_prismcode_md_policy_admission_for_launch(Some(&admission), true)
            .expect("governed launch admission")
            .expect("retained admission");
        assert!(std::ptr::eq(retained, &admission));
        assert_eq!(retained.packet_sha256, "b".repeat(64));
        assert_eq!(retained.packet_hash_blake3, "a".repeat(64));
        assert_eq!(retained.policy, expected);
    }

    #[test]
    fn therm_postmd_launch_retains_its_distinct_authorized_profile() {
        let expected = MdEnginePolicyV1::therm_postmd();
        let admission =
            admit_prismcode_md_policy_before_cuda(Some(&validated(expected.clone())), &expected)
                .expect("exact Therm profile admission");
        let retained = require_prismcode_md_policy_admission_for_launch(Some(&admission), true)
            .expect("strict Therm policy is supported")
            .expect("retained admission");
        assert_eq!(retained.policy, expected);
        assert_ne!(retained.policy, MdEnginePolicyV1::canonical_hyper_runtime());
    }
}

#[cfg(feature = "gpu")]
fn tier8_director_driver_error_text(rc: sys::CUresult) -> (String, String) {
    let err = DriverError(rc);
    let name = err
        .error_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|e| format!("cuGetErrorName failed: {:?}", e));
    let text = err
        .error_string()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|e| format!("cuGetErrorString failed: {:?}", e));
    (name, text)
}

#[cfg(feature = "gpu")]
fn tier8_director_diag_verbose_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var("PRISM_TIER8_VERBOSE_DIAG")
            .ok()
            .map(|v| {
                let v = v.trim();
                v == "1"
                    || v.eq_ignore_ascii_case("true")
                    || v.eq_ignore_ascii_case("yes")
                    || v.eq_ignore_ascii_case("on")
            })
            .unwrap_or(false)
    })
}

#[cfg(feature = "gpu")]
macro_rules! tier8_director_diag_verbose {
    ($($arg:tt)*) => {
        if tier8_director_diag_verbose_enabled() {
            log::info!($($arg)*);
        }
    };
}

