static DURABLE_JSON_TEMP_COUNTER: AtomicU64 = AtomicU64::new(0);
#[cfg(feature = "gpu")]
static LADD_CADENCE_DOMAIN_COUNTER: AtomicU64 = AtomicU64::new(1);

#[cfg(feature = "gpu")]
fn sha256_hex(bytes: &[u8]) -> String {
    use sha2::Digest;
    format!("{:x}", sha2::Sha256::digest(bytes))
}

#[cfg(feature = "gpu")]
fn require_equivalent_durable_json(
    path: &Path,
    encoded: &[u8],
    authoritative_value: &serde_json::Value,
) -> Result<()> {
    let metadata = std::fs::symlink_metadata(path)
        .with_context(|| format!("inspect existing durable receipt {}", path.display()))?;
    if !metadata.file_type().is_file() {
        bail!(
            "existing durable receipt is not a regular file: {}",
            path.display()
        );
    }
    let existing = std::fs::read(path)
        .with_context(|| format!("read existing durable receipt {}", path.display()))?;
    if existing != encoded {
        let existing_value: serde_json::Value =
            serde_json::from_slice(&existing).with_context(|| {
                format!(
                    "existing durable receipt is not equivalent JSON: {}",
                    path.display()
                )
            })?;
        if existing_value != *authoritative_value {
            bail!(
                "existing durable receipt conflicts with authoritative runtime identity: {}",
                path.display()
            );
        }
    }
    std::fs::File::open(path)?.sync_all()?;
    Ok(())
}

#[cfg(feature = "gpu")]
fn write_durable_json(path: &Path, value: &serde_json::Value) -> Result<()> {
    let parent = path
        .parent()
        .filter(|candidate| !candidate.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    std::fs::create_dir_all(parent)?;
    let mut encoded = serde_json::to_vec_pretty(value)?;
    encoded.push(b'\n');

    match std::fs::symlink_metadata(path) {
        Ok(_) => {
            require_equivalent_durable_json(path, &encoded, value)?;
            std::fs::File::open(parent)?.sync_all()?;
            return Ok(());
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => {
            return Err(error)
                .with_context(|| format!("inspect durable receipt target {}", path.display()));
        }
    }

    let (temporary, mut file) = loop {
        let nonce = DURABLE_JSON_TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
        let candidate = parent.join(format!(
            ".{}.{}.{}.tmp",
            path.file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("force-kernel-receipt"),
            std::process::id(),
            nonce
        ));
        match std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&candidate)
        {
            Ok(file) => break (candidate, file),
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(error) => {
                return Err(error)
                    .with_context(|| format!("create temporary receipt {}", candidate.display()));
            }
        }
    };
    file.write_all(&encoded)?;
    file.sync_all()?;
    drop(file);

    match std::fs::hard_link(&temporary, path) {
        Ok(()) => {}
        Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
            let equivalence = require_equivalent_durable_json(path, &encoded, value);
            std::fs::remove_file(&temporary)
                .with_context(|| format!("remove temporary receipt {}", temporary.display()))?;
            equivalence?;
            std::fs::File::open(parent)?.sync_all()?;
            return Ok(());
        }
        Err(error) => {
            let _ = std::fs::remove_file(&temporary);
            return Err(error).with_context(|| {
                format!(
                    "atomically publish durable receipt {} from {}",
                    path.display(),
                    temporary.display()
                )
            });
        }
    }
    std::fs::remove_file(&temporary)
        .with_context(|| format!("remove temporary receipt {}", temporary.display()))?;
    std::fs::File::open(parent)?.sync_all()?;
    require_equivalent_durable_json(path, &encoded, value)?;
    Ok(())
}

#[cfg(all(test, feature = "gpu"))]
mod durable_json_tests {
    use super::write_durable_json;
    use std::os::unix::fs::MetadataExt;
    use std::sync::{Arc, Barrier};

    #[test]
    fn concurrent_identical_publication_is_idempotent() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let receipt = directory.path().join("force-kernel-receipt.json");
        let value = Arc::new(serde_json::json!({
            "status": "PASS",
            "decoded_ptx_sha256": "a".repeat(64),
            "packet_sha256": "b".repeat(64),
            "fallback_allowed": false,
        }));
        let writers = 16;
        let barrier = Arc::new(Barrier::new(writers));
        let handles = (0..writers)
            .map(|_| {
                let barrier = Arc::clone(&barrier);
                let value = Arc::clone(&value);
                let receipt = receipt.clone();
                std::thread::spawn(move || {
                    barrier.wait();
                    write_durable_json(&receipt, &value)
                })
            })
            .collect::<Vec<_>>();

        for handle in handles {
            handle.join().expect("writer thread").expect("publication");
        }

        let published: serde_json::Value =
            serde_json::from_slice(&std::fs::read(&receipt).expect("published receipt"))
                .expect("valid published JSON");
        assert_eq!(published, *value);
        let remaining = std::fs::read_dir(directory.path())
            .expect("receipt directory")
            .map(|entry| entry.expect("directory entry").path())
            .collect::<Vec<_>>();
        assert_eq!(remaining, vec![receipt]);
    }

    #[test]
    fn semantically_equivalent_existing_receipt_is_preserved() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let receipt = directory.path().join("force-kernel-receipt.json");
        let compact = br#"{"fallback_allowed":false,"status":"PASS"}"#;
        std::fs::write(&receipt, compact).expect("seed compact receipt");
        let inode_before = std::fs::metadata(&receipt).expect("metadata").ino();

        write_durable_json(
            &receipt,
            &serde_json::json!({"status": "PASS", "fallback_allowed": false}),
        )
        .expect("semantic idempotence");

        assert_eq!(std::fs::read(&receipt).expect("readback"), compact);
        assert_eq!(
            std::fs::metadata(&receipt).expect("metadata").ino(),
            inode_before
        );
    }

    #[test]
    fn conflicting_existing_receipt_fails_closed() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let receipt = directory.path().join("force-kernel-receipt.json");
        let original = serde_json::json!({
            "status": "PASS",
            "packet_sha256": "a".repeat(64),
        });
        write_durable_json(&receipt, &original).expect("initial publication");
        let original_bytes = std::fs::read(&receipt).expect("initial readback");

        let error = write_durable_json(
            &receipt,
            &serde_json::json!({
                "status": "PASS",
                "packet_sha256": "b".repeat(64),
            }),
        )
        .expect_err("conflicting publication must fail");

        assert!(error
            .to_string()
            .contains("conflicts with authoritative runtime identity"));
        assert_eq!(
            std::fs::read(&receipt).expect("final readback"),
            original_bytes
        );
    }
}

#[cfg(feature = "gpu")]
fn validate_force_kernel_trust_manifest(
    decoded_bytes: &[u8],
    packet_bytes: &[u8],
) -> Result<serde_json::Value> {
    let manifest_path_raw = std::env::var("PRISMCODE_CUDA_TRUST_MANIFEST").context(
        "FATAL: PRISMCODE_CUDA_TRUST_MANIFEST is required for configured QNANL force-kernel execution",
    )?;
    let manifest_path = PathBuf::from(&manifest_path_raw);
    let manifest_bytes = std::fs::read(&manifest_path)
        .with_context(|| format!("read CUDA trust manifest {}", manifest_path.display()))?;
    let manifest: serde_json::Value = serde_json::from_slice(&manifest_bytes)
        .with_context(|| format!("parse CUDA trust manifest {}", manifest_path.display()))?;
    let decoded_sha256 = sha256_hex(decoded_bytes);
    let decoded_blake3 = blake3::hash(decoded_bytes).to_hex().to_string();
    let packet_sha256 = sha256_hex(packet_bytes);
    let packet_blake3 = blake3::hash(packet_bytes).to_hex().to_string();
    let binding = manifest
        .get("blackwell_runtime_binding")
        .context("CUDA trust manifest lacks blackwell_runtime_binding")?;
    let binding_matches = binding
        .get("full_force_kernel_ptx_sha256")
        .and_then(|value| value.as_str())
        == Some(decoded_sha256.as_str())
        && binding
            .get("full_force_kernel_ptx_blake3")
            .and_then(|value| value.as_str())
            == Some(decoded_blake3.as_str())
        && binding
            .get("full_force_kernel_ptx_bytes")
            .and_then(|value| value.as_u64())
            == Some(decoded_bytes.len() as u64);
    let ptx_row_matches = manifest
        .get("ptx_hashes")
        .and_then(|value| value.as_array())
        .map(|rows| {
            rows.iter().any(|row| {
                row.get("family").and_then(|value| value.as_str()) == Some("MD_FORCE_KERNEL_PTX")
                    && row.get("sha256").and_then(|value| value.as_str())
                        == Some(decoded_sha256.as_str())
                    && row.get("blake3").and_then(|value| value.as_str())
                        == Some(decoded_blake3.as_str())
            })
        })
        .unwrap_or(false);
    let packet_binding = manifest
        .get("force_kernel_qnanl_binding")
        .context("CUDA trust manifest lacks force_kernel_qnanl_binding")?;
    let packet_binding_matches = packet_binding
        .get("packet_sha256")
        .and_then(|value| value.as_str())
        == Some(packet_sha256.as_str())
        && packet_binding
            .get("packet_blake3")
            .and_then(|value| value.as_str())
            == Some(packet_blake3.as_str())
        && packet_binding
            .get("decoded_ptx_sha256")
            .and_then(|value| value.as_str())
            == Some(decoded_sha256.as_str())
        && packet_binding
            .get("decoded_ptx_blake3")
            .and_then(|value| value.as_str())
            == Some(decoded_blake3.as_str());
    if !binding_matches || !ptx_row_matches || !packet_binding_matches {
        bail!(
            "FATAL: QNANL force-kernel packet/decoded PTX does not match CUDA trust manifest {}: decoded_sha256={} decoded_blake3={} packet_sha256={} packet_blake3={} binding_matches={} ptx_row_matches={} packet_binding_matches={}",
            manifest_path.display(),
            decoded_sha256,
            decoded_blake3,
            packet_sha256,
            packet_blake3,
            binding_matches,
            ptx_row_matches,
            packet_binding_matches
        );
    }
    Ok(serde_json::json!({
        "status": "PASS",
        "path": manifest_path.display().to_string(),
        "manifest_sha256": sha256_hex(&manifest_bytes),
        "ptx_sha256": decoded_sha256,
        "ptx_blake3": decoded_blake3,
        "ptx_bytes": decoded_bytes.len(),
        "packet_sha256": packet_sha256,
        "packet_blake3": packet_blake3,
        "packet_bytes": packet_bytes.len(),
        "blackwell_runtime_binding_match": true,
        "ptx_hash_row_match": true,
        "qnanl_packet_binding_match": true,
    }))
}

#[cfg(feature = "gpu")]
pub fn load_qnanl_force_kernel_module_if_configured(
    context: &Arc<CudaContext>,
) -> Result<Option<(Arc<CudaModule>, String)>> {
    Ok(
        load_qnanl_force_kernel_module_if_configured_with_text(context)?
            .map(|(module, label, _text)| (module, label)),
    )
}

/// Same as [`load_qnanl_force_kernel_module_if_configured`], but ALSO returns
/// the decoded PTX text.
///
/// The QNANL path decodes PTX in memory and labels the module
/// `"QNANL:<packet>"`, which is not a readable file. Any ABI check that reads
/// the "path" therefore degrades to UNVERIFIED on exactly the lane the
/// appliance runs. Callers that verify kernel ABIs MUST use this form so the
/// check inspects the bytes that were actually loaded.
pub fn load_qnanl_force_kernel_module_if_configured_with_text(
    context: &Arc<CudaContext>,
) -> Result<Option<(Arc<CudaModule>, String, Option<String>)>> {
    let Ok(packet_path_raw) = std::env::var(PRISMOS_QNANL_FORCE_KERNEL_PACKET_ENV) else {
        return Ok(None);
    };
    let packet_path = PathBuf::from(&packet_path_raw);
    if !packet_path.is_file() {
        bail!(
            "FATAL: configured QNANL force-kernel packet is missing: {}={}",
            PRISMOS_QNANL_FORCE_KERNEL_PACKET_ENV,
            packet_path.display()
        );
    }
    let header = qnanl_artifact::packet_header(&packet_path).with_context(|| {
        format!(
            "FATAL: read QNANL force-kernel packet header {}",
            packet_path.display()
        )
    })?;
    if header.artifact_family != QnanlArtifactFamily::MdForceKernelPtx
        || header.artifact_transform != "PTX_CANONICAL_BYTES"
    {
        bail!(
            "FATAL: QNANL force-kernel packet contract mismatch: family={} transform={}",
            header.artifact_family,
            header.artifact_transform
        );
    }
    let source_file_name = header.source_file_name.as_deref().unwrap_or_default();
    if header.artifact_id != NHS_AMBER_FUSED_PTX_ARTIFACT_ID
        || source_file_name != NHS_AMBER_FUSED_PTX_ARTIFACT_ID
    {
        bail!(
            "FATAL: QNANL force-kernel identity mismatch: artifact_id={} source_file_name={}",
            header.artifact_id,
            source_file_name
        );
    }
    for required_codec in ["PTX_CANONICAL_BYTES", "SECTION_ZSTD", "QNANL_Q4_SEAL"] {
        if !header
            .codec_stack
            .iter()
            .any(|codec| codec == required_codec)
        {
            bail!(
                "FATAL: QNANL force-kernel packet lacks required codec/seal stage {}",
                required_codec
            );
        }
    }
    let packet_bytes = std::fs::read(&packet_path).with_context(|| {
        format!(
            "FATAL: read QNANL force-kernel packet {}",
            packet_path.display()
        )
    })?;
    let decoded_ptx = qnanl_artifact::decode_packet_bytes(&packet_bytes).with_context(|| {
        format!(
            "FATAL: QNANL force-kernel seal/ECC/Merkle/decode verification failed for {}",
            packet_path.display()
        )
    })?;
    if decoded_ptx.len() as u64 != header.raw_bytes
        || blake3::hash(&decoded_ptx).to_hex().to_string() != header.raw_hash_blake3
    {
        bail!("FATAL: QNANL force-kernel decoded size/hash differs from packet header");
    }
    let trust_manifest = validate_force_kernel_trust_manifest(&decoded_ptx, &packet_bytes)?;
    let ptx_src = String::from_utf8(decoded_ptx.clone()).with_context(|| {
        format!(
            "FATAL: QNANL-decoded force kernel is not UTF-8 PTX: {}",
            packet_path.display()
        )
    })?;
    let module = context
        .load_module(Ptx::from_src(ptx_src))
        .with_context(|| {
            format!(
                "FATAL: CUDA rejected QNANL-decoded force-kernel PTX {}",
                packet_path.display()
            )
        })?;
    let required_symbols = [
        "nhs_amber_fused_step",
        "nhs_amber_phase_force_n_v1",
        "nhs_amber_phase_ou_half_kick_n_v1",
        "nhs_amber_phase_rattle_pre_drift_v1",
        "nhs_amber_phase_drift_save_xn_v1",
        "nhs_amber_phase_shake_position_v1",
        "nhs_amber_phase_force_np1_v1",
        "nhs_amber_phase_kick_np1_ou_half_v1",
        "nhs_amber_phase_ou_half_n_v1",
        "nhs_amber_phase_rattle_after_ou_n_v1",
        "nhs_amber_phase_kick_n_v1",
        "nhs_amber_phase_kick_np1_v1",
        "nhs_amber_phase_rattle_before_ou_np1_v1",
        "nhs_amber_phase_ou_half_np1_v1",
        "nhs_nma_phase_fused_v1",
        "nhs_harmonic_parameter_observe_v1",
        "nhs_voxel_step",
        "nhs_uv_pump_probe_step",
        "nhs_uv_charge_state_snapshot",
        "nhs_uv_charge_parameter_work",
        "nhs_reduce_external_work_components",
        "nhs_velocity_safety_clamp",
        "nhs_rattle_velocity_constraints",
        "init_rng_states",
        "init_lif_state",
        "init_warp_matrix",
        "nhs_voxel_step_multi_lif",
        "init_multi_neuron",
        "nhs_build_coupling_from_spike_grid",
        "build_aromatic_neighbors",
        "compute_ring_normals",
        "reset_cell_counts",
        "build_cell_list",
        "build_neighbor_list",
        "nhs_build_neighbor_list_warp",
        "compute_nonbonded_neighborlist",
        "kcc_residue_update",
        "kcc_residue_update_protocol",
        "kcc_compute_rich_descriptors",
    ];
    for symbol in required_symbols {
        module.load_function(symbol).with_context(|| {
            format!(
                "FATAL: required CUDA symbol {} is absent from QNANL-decoded force kernel",
                symbol
            )
        })?;
    }
    let loaded_path = format!("QNANL:{}", packet_path.display());
    if let Ok(receipt_path_raw) = std::env::var(PRISMOS_QNANL_FORCE_KERNEL_RECEIPT_ENV) {
        let receipt_path = PathBuf::from(receipt_path_raw);
        let receipt = serde_json::json!({
            "schema_kind": "prismos_qnanl_force_kernel_runtime_receipt",
            "schema_version": 3,
            "status": "PASS",
            "implementation_status": "IMPLEMENTATION_VERIFIED",
            "build_authority": "NATIVE_PTX",
            "runtime_load_authority": "QNANL_DECODED_PTX",
            "packet_path": packet_path.display().to_string(),
            "packet_bytes": packet_bytes.len(),
            "packet_sha256": sha256_hex(&packet_bytes),
            "packet_blake3": blake3::hash(&packet_bytes).to_hex().to_string(),
            "artifact_id": header.artifact_id,
            "artifact_family": header.artifact_family.to_string(),
            "artifact_transform": header.artifact_transform,
            "codec_stack": header.codec_stack,
            "decoded_ptx_bytes": decoded_ptx.len(),
            "decoded_ptx_sha256": sha256_hex(&decoded_ptx),
            "decoded_ptx_blake3": blake3::hash(&decoded_ptx).to_hex().to_string(),
            "packet_validation": {
                "status": "PASS",
                "roundtrip_verified": true,
                "seal_constraints_pass": true,
                "merkle_verified": true,
                "ecc_verified": true,
            },
            "trust_manifest": trust_manifest,
            "loaded_module": loaded_path,
            "required_cuda_symbols": required_symbols.as_slice(),
            "all_required_cuda_symbols_resolved": true,
            "fallback_allowed": false,
        });
        write_durable_json(&receipt_path, &receipt).with_context(|| {
            format!(
                "durably write QNANL force-kernel runtime receipt {}",
                receipt_path.display()
            )
        })?;
    }
    // Carry the DECODED PTX TEXT out, not just a pseudo-path. The ABI checker
    // must inspect the bytes that were actually loaded; on this path the
    // "path" is the synthetic string "QNANL:<packet>", which no filesystem
    // read can resolve, so a path-only checker degrades to UNVERIFIED exactly
    // on the lane the appliance uses.
    let decoded_ptx_text = String::from_utf8(decoded_ptx.clone()).ok();
    Ok(Some((module, loaded_path, decoded_ptx_text)))
}

