/// Maximum grid dimension (must match CUDA MAX_GRID_DIM=128)
const MAX_GRID_DIM: usize = 128; // Must match CUDA MAX_GRID_DIM in nhs_amber_fused.cu

/// Block size for 1D kernels
const BLOCK_SIZE_1D: usize = 256;

/// Spread small atom-owned workloads over more SMs: 2790 atoms expose 44
/// blocks at 64 threads instead of only 11 at 256. These call sites have no
/// block reductions; each atom (or grid-strided constraint cluster) retains
/// its own arithmetic order. Fixed-size reduction kernels must not use this.
fn atom_owned_launch_config(n_atoms: usize) -> LaunchConfig {
    let threads = if n_atoms < 16_384 {
        64u32
    } else {
        BLOCK_SIZE_1D as u32
    };
    LaunchConfig {
        grid_dim: ((n_atoms.max(1) as u32).div_ceil(threads), 1, 1),
        block_dim: (threads, 1, 1),
        shared_mem_bytes: 0,
    }
}

/// nhs_build_neighbor_list_warp assigns one atom per warp, eight per block.
/// Its 32 KiB shared rows are statically allocated by the CUDA kernel.
fn warp_neighbor_launch_config(n_atoms: usize) -> LaunchConfig {
    LaunchConfig {
        grid_dim: ((n_atoms.max(1) as u32).div_ceil(8), 1, 1),
        block_dim: (256, 1, 1),
        shared_mem_bytes: 0,
    }
}

// A source-owned phase map shared by selection, ABI checks and witnesses.
// Legacy runtime-phase ABI remains the full fallback for unknown phase IDs.
const AMBER_PHASE_SPECIALIZATIONS: [(i32, &str); 13] = [
    (0, "nhs_amber_phase_force_n_v1"),
    (1, "nhs_amber_phase_ou_half_kick_n_v1"),
    (2, "nhs_amber_phase_rattle_pre_drift_v1"),
    (3, "nhs_amber_phase_drift_save_xn_v1"),
    (4, "nhs_amber_phase_shake_position_v1"),
    (5, "nhs_amber_phase_force_np1_v1"),
    (6, "nhs_amber_phase_kick_np1_ou_half_v1"),
    (10, "nhs_amber_phase_ou_half_n_v1"),
    (11, "nhs_amber_phase_rattle_after_ou_n_v1"),
    (12, "nhs_amber_phase_kick_n_v1"),
    (13, "nhs_amber_phase_kick_np1_v1"),
    (14, "nhs_amber_phase_rattle_before_ou_np1_v1"),
    (15, "nhs_amber_phase_ou_half_np1_v1"),
];

#[cfg(feature = "gpu")]
fn select_amber_phase_kernel(
    legacy: &CudaFunction, specialized: &[CudaFunction; 13], execution_phase: i32,
) -> (CudaFunction, &'static str) {
    // Keep the established full-body force export for both force endpoints.
    // Nonforce phases retain their compile-time specialization. CUDA bodies,
    // argument values/order and launch geometry are unchanged by this policy.
    if execution_phase == MD_PHASE_FORCE_N || execution_phase == MD_PHASE_FORCE_NP1 {
        return (legacy.clone(), "nhs_amber_fused_step");
    }
    match AMBER_PHASE_SPECIALIZATIONS.iter().position(|(phase, _)| *phase == execution_phase) {
        Some(index) => (specialized[index].clone(), AMBER_PHASE_SPECIALIZATIONS[index].1),
        None => (legacy.clone(), "nhs_amber_fused_step"),
    }
}

#[cfg(feature = "gpu")]
fn amber_specialized_phase_opcodes(phase: i32) -> &'static [&'static str] {
    match phase {
        MD_PHASE_FORCE_N | MD_PHASE_FORCE_NP1 => &[pcmd::OP_MD_FORCE_BONDED, pcmd::OP_MD_FORCE_NONBONDED],
        MD_PHASE_RATTLE_PRE_DRIFT | MD_PHASE_RATTLE_AFTER_OU_N |
        MD_PHASE_RATTLE_BEFORE_OU_NP1 | MD_PHASE_SHAKE_POSITION => &[pcmd::OP_MD_SHAKE_CONSTRAIN],
        _ => &[pcmd::OP_MD_INTEGRATE_VELOCITY_VERLET],
    }
}

