/// Opaque, crate-internal capability to dispatch one cadence-boundary LADD
/// sample. It is deliberately non-clonable and has no public constructor or
/// fields: only the persistent graph-bound orchestration may issue it.
#[cfg(feature = "gpu")]
#[derive(Debug)]
pub(crate) struct LaddCadenceBoundary {
    domain: u64,
    nonce: u64,
}

/// Opaque, crate-internal capability to commit one already-enqueued
/// cadence-boundary LADD update.  It is consumed exactly once by
/// `commit_ladd_cadence_dispatch_after_sync` after a verified synchronization.
#[cfg(feature = "gpu")]
#[derive(Debug)]
pub(crate) struct LaddCadenceDispatch {
    domain: u64,
    nonce: u64,
}

#[cfg(feature = "gpu")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum LaddCadencePhase {
    Begun,
    Dispatching,
    Dispatched,
    Poisoned,
}

/// Engine-owned LADD evidence state. The crate-internal boundary/dispatch
/// values are opaque capabilities; all physical fields remain here so callers
/// cannot fabricate, alter, or replay a scientific receipt lineage.
#[cfg(feature = "gpu")]
#[derive(Clone, Copy, Debug)]
struct LaddCadencePending {
    nonce: u64,
    phase: LaddCadencePhase,
    replica_epoch: u32,
    start_device_step: u32,
    cadence_physical_steps: u32,
    end_device_step: u32,
    host_timestep_mirror: i32,
    grid_dim: [u32; 3],
    block_dim: [u32; 3],
    shared_mem_bytes: u32,
}

