pub const OBSERVER_PHYSICAL_CLOCK_ABI: u32 = 1;
/// Exact actual-device timestep chronology. f64 values preserve the widened
/// integrator f32 dt and device round-to-nearest cumulative sum, never nominal dt.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct ObserverPhysicalTimeRecord {
    pub step: u64,
    pub applied_dt_ps: f64,
    pub cumulative_simulated_time_ps: f64,
}
const _: () = assert!(std::mem::size_of::<ObserverPhysicalTimeRecord>() == 24);

#[cfg(feature = "gpu")]
struct HarmonicObservationPlan {
    n_atoms: i32, n_bonds: i32, n_angles: i32,
    bf: usize, be: usize, af: usize, ae: usize,
    coordinates: usize, bond_bytes: usize, angle_bytes: usize,
    scratch_bytes: usize, payload_bytes: usize,
}

#[cfg(feature = "gpu")]
const MAX_HARMONIC_OBSERVATION_PAYLOAD_BYTES: usize = 64 * 1024 * 1024;

/// Exact finite scratch/payload admission, before any engine-owned allocation.
/// The same plan is recomputed at observation; no population truncation exists.
#[cfg(feature = "gpu")]
fn harmonic_observation_plan(atoms: usize, bonds: usize, angles: usize) -> Result<HarmonicObservationPlan> {
    anyhow::ensure!(cfg!(target_endian = "little"), "harmonic struct ABI requires little endian host");
    anyhow::ensure!(std::mem::size_of::<GpuBondParam>() == 16
        && std::mem::size_of::<GpuAngleParam>() == 20, "harmonic host/CUDA struct shape mismatch");
    let n_atoms = i32::try_from(atoms).context("harmonic observer atom count exceeds i32")?;
    let n_bonds = i32::try_from(bonds).context("harmonic observer bond count exceeds i32")?;
    let n_angles = i32::try_from(angles).context("harmonic observer angle count exceeds i32")?;
    let count = |n: usize, width: usize| n.checked_mul(width).context("harmonic observation size overflow");
    let bf = count(bonds,6)?; let be = count(bonds,2)?;
    let af = count(angles,9)?; let ae = count(angles,3)?;
    let coordinates = count(atoms,3)?;
    let bond_bytes = count(bonds,16)?; let angle_bytes = count(angles,20)?;
    let scratch_bytes = [count(bf.max(1),4)?,count(be.max(1),8)?,count(af.max(1),4)?,count(ae.max(1),8)?,16usize]
        .into_iter().try_fold(0usize,|a,b|a.checked_add(b).context("harmonic scratch overflow"))?;
    let payload_bytes = [scratch_bytes,count(coordinates,4)?,bond_bytes,angle_bytes]
        .into_iter().try_fold(0usize,|a,b|a.checked_add(b).context("harmonic payload overflow"))?;
    anyhow::ensure!(payload_bytes <= MAX_HARMONIC_OBSERVATION_PAYLOAD_BYTES,
        "complete harmonic observation requires {} bytes, exceeds explicit {} byte admission; no truncation allowed",
        payload_bytes, MAX_HARMONIC_OBSERVATION_PAYLOAD_BYTES);
    Ok(HarmonicObservationPlan {n_atoms,n_bonds,n_angles,bf,be,af,ae,coordinates,
        bond_bytes,angle_bytes,scratch_bytes,payload_bytes})
}

