        device::validate(by_name["d_dihedrals"], Some(&self.d_dihedrals))?;
        device::validate(by_name["d_lj_params"], Some(&self.d_lj_params))?;
        device::validate(by_name["d_exclusion_list"], Some(&self.d_exclusion_list))?;
