impl NhsAmberFusedEngine {
    /// Device-authored selector at an already synchronized native window.
    pub fn checkpoint_device_coupling_parity(&self)->Result<u8>{
        let offset=std::mem::offset_of!(crate::protocol_state::ProtocolState,coupling_phase);
        anyhow::ensure!(self.d_protocol_state.len()>=offset+4,"ProtocolState coupling selector ABI truncated");
        let mut bytes=[0u8;4];self.stream.memcpy_dtoh(&self.d_protocol_state.slice(offset..offset+4),&mut bytes)?;
        self.synchronize_stream_raw("checkpoint coupling selector")?;
        let parity=i32::from_ne_bytes(bytes);anyhow::ensure!((0..=1).contains(&parity),"native coupling selector invalid");Ok(parity as u8)
    }
}


#[cfg(feature="gpu")]
#[derive(Clone,Debug,serde::Serialize,serde::Deserialize)]
pub struct ScientificFieldPlan {
    pub contract:crate::scientific_checkpoint::FieldContract,
    pub present_bytes:Option<u64>,
    pub temporary_bytes:u64,
}
/// Nonserializable same-engine plan held through an immutable borrow. Only
/// this module constructs it, immediately from the complete live field factory.
/// It cannot be supplied by a capsule or edited by a caller between admission
/// and streaming. Mutable engine operations require this borrow to end first.
#[cfg(feature="gpu")]
pub struct PreparedScientificFieldPlan<'a> {
    engine: &'a NhsAmberFusedEngine,
    owner: String,
    maximum_logical_bytes: u64,
    fields: Vec<ScientificFieldPlan>,
}
#[cfg(feature="gpu")]
impl PreparedScientificFieldPlan<'_> {
    pub fn fields(&self) -> &[ScientificFieldPlan] { &self.fields }
}
#[cfg(feature="gpu")]
fn device_plan<T:crate::scientific_checkpoint::device::PlaneElement>(owner:&str,name:&str,plane:Option<&CudaSlice<T>>,optional:bool)->Result<ScientificFieldPlan> {
    let present_bytes=plane.map(|v|(v.len() as u64).checked_mul(T::WIDTH as u64).context("device field size overflow")).transpose()?;
    anyhow::ensure!(present_bytes.is_some()||optional,"required scientific plane absent");
    Ok(ScientificFieldPlan{contract:crate::scientific_checkpoint::FieldContract{owner:owner.into(),name:name.into(),encoding:T::ENCODING.into(),expected_bytes:present_bytes,may_be_absent:optional},present_bytes,temporary_bytes:present_bytes.unwrap_or(0).checked_mul(2).context("device transfer scratch overflow")?})
}
#[cfg(feature="gpu")]
fn host_plan<T:serde::Serialize+?Sized>(owner:&str,name:&str,value:&T,max:u64)->Result<ScientificFieldPlan> {
    let (size,heap)=crate::checkpoint_codec::allocation_plan(value,max)?;
    Ok(ScientificFieldPlan{contract:crate::scientific_checkpoint::FieldContract{owner:owner.into(),name:name.into(),encoding:"prism.typed-host-state.v1".into(),expected_bytes:None,may_be_absent:false},present_bytes:Some(size),temporary_bytes:heap})
}
#[cfg(feature="gpu")]
static NATIVE_SPIKE_ARCHIVE_INSTANCE:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(1);
#[cfg(feature="gpu")]
fn next_native_spike_archive_instance()->u64 {
    NATIVE_SPIKE_ARCHIVE_INSTANCE.fetch_update(std::sync::atomic::Ordering::Relaxed,std::sync::atomic::Ordering::Relaxed,|n|n.checked_add(1)).expect("native archive instance identity exhausted")
}
