        let native_bytes=(self.accumulated_spikes.len() as u64).checked_mul(PRISM_SPIKE_RECORD_BYTES as u64).context("native archive extent overflow")?;
        anyhow::ensure!(native_bytes<=max_field_bytes,"native archive field exceeds decoded generation cap");
        plans.push(ScientificFieldPlan{contract:crate::scientific_checkpoint::FieldContract{owner:owner.into(),name:"accumulated_spikes".into(),
            encoding:crate::scientific_checkpoint::native_spike_archive::NATIVE_SPIKE_ARCHIVE_ENCODING.into(),expected_bytes:None,may_be_absent:false},
            present_bytes:Some(native_bytes),temporary_bytes:native_bytes.checked_mul(4).and_then(|n|n.checked_add(128)).context("native archive heap budget overflow")?});
        plans.push(host_plan(owner,"live_monitor_frame_id",&self.live_monitor_frame_id,max_field_bytes)?);
