        plans.push(host_plan(owner,"ladd_cadence_nonce",&self.ladd_cadence_nonce,max_field_bytes)?);
        let trace_json_bytes=self.prismcode_md_runtime.as_ref().map(|v|v.process_checkpoint_size_bytes(512*1024*1024)).transpose()?;
        let trace_wire_bytes=match trace_json_bytes {Some(n)=>18u64.checked_add(n.checked_mul(9).context("typed trace extent overflow")?).context("typed trace extent overflow")?,None=>9};
        anyhow::ensure!(trace_wire_bytes<=max_field_bytes,"native trace field exceeds preallocation budget");
        plans.push(ScientificFieldPlan{contract:crate::scientific_checkpoint::FieldContract{owner:owner.into(),name:"prismcode_md_runtime".into(),encoding:"prism.typed-host-state.v1".into(),expected_bytes:None,may_be_absent:false},present_bytes:Some(trace_wire_bytes),temporary_bytes:trace_json_bytes.unwrap_or(0).checked_mul(256).and_then(|n|n.checked_add(4096)).context("trace JSON/typed restore budget overflow")?});
        if let Some(c)=&self.biprism_coordinates {
            plans.push(host_plan(owner,"biprism_coordinate_identity",&c.identity,max_field_bytes)?);
            plans.push(device_plan(owner,"biprism_coordinate_current_low",Some(&c.current_low),false)?);
            plans.push(device_plan(owner,"biprism_coordinate_step_start_low",Some(&c.step_start_low),false)?);
            plans.push(device_plan(owner,"biprism_coordinate_reference_high",Some(&c.reference_high),false)?);
            plans.push(device_plan(owner,"biprism_coordinate_reference_low",Some(&c.reference_low),false)?);
        }
        for p in &plans {anyhow::ensure!(p.present_bytes.unwrap_or(0)<=max_field_bytes,"scientific field exceeds admitted capture memory before allocation: {}",p.contract.key());}
        Ok(plans)
