#[cfg(feature="gpu")]
struct NativeJsonAsTypedBytes<'a>{out:&'a mut dyn std::io::Write,count:u64,expected:u64}
#[cfg(feature="gpu")]
impl std::io::Write for NativeJsonAsTypedBytes<'_> {
    fn write(&mut self,bytes:&[u8])->std::io::Result<usize>{
        if self.count.checked_add(bytes.len() as u64).is_none_or(|n|n>self.expected){return Err(std::io::Error::new(std::io::ErrorKind::InvalidData,"PrismCode JSON exceeds admitted bytes"));}
        let mut encoded=[0u8;9*4096];
        for chunk in bytes.chunks(4096){for (slot,value) in encoded.chunks_exact_mut(9).zip(chunk){slot[0]=4;slot[1..].copy_from_slice(&(*value as u64).to_le_bytes());}self.out.write_all(&encoded[..chunk.len()*9])?;}
        self.count+=bytes.len() as u64;Ok(bytes.len())
    }
    fn flush(&mut self)->std::io::Result<()>{self.out.flush()}
}
